<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/bootstrap.php';
$pageTitle='Verifikasi Surat Siswa';
if(!$pdo){http_response_code(500);exit('Database belum tersambung.');}
if(empty($_SESSION['role'])||!in_array($_SESSION['role'],['admin','guru'],true)){http_response_code(403);require __DIR__.'/../../includes/header.php';echo '<section class="panel"><h2>Akses dibatasi</h2><p>Halaman verifikasi hanya untuk akun admin atau guru yang sudah diautentikasi. Hubungkan pemeriksaan ini dengan sistem login sekolah sebelum digunakan.</p></section>';require __DIR__.'/../../includes/footer.php';exit;}
if(empty($_SESSION['csrf_verifikasi']))$_SESSION['csrf_verifikasi']=bin2hex(random_bytes(32));
$notice='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf_verifikasi'],(string)($_POST['csrf']??'')))$errors[]='Sesi formulir tidak valid.';
 else{$id=(int)($_POST['id']??0);$decision=$_POST['keputusan']??'';$note=trim((string)($_POST['catatan']??''));if($id<1||!in_array($decision,['disetujui','ditolak'],true))$errors[]='Pengajuan atau keputusan tidak valid.';elseif(mb_strlen($note)>500)$errors[]='Catatan maksimal 500 karakter.';else{$q=$pdo->prepare("UPDATE pengajuan_surat_absensi SET status=?,catatan_verifikasi=?,diverifikasi_oleh=?,diverifikasi_pada=NOW() WHERE id=? AND status='menunggu'");$q->execute([$decision,$note,mb_substr((string)($_SESSION['nama']??$_SESSION['username']??'Petugas'),0,150),$id]);$notice=$q->rowCount()?'Status pengajuan berhasil diperbarui.':'Pengajuan tidak ditemukan atau sudah diverifikasi.';}}
}
$status=$_GET['status']??'menunggu';if(!in_array($status,['menunggu','disetujui','ditolak','semua'],true))$status='menunggu';
$sql="SELECT a.*,s.nama,s.nisn,s.nis,s.rombel FROM pengajuan_surat_absensi a JOIN siswa s ON s.id=a.siswa_id";$params=[];if($status!=='semua'){$sql.=" WHERE a.status=?";$params[]=$status;}$sql.=" ORDER BY a.created_at DESC LIMIT 300";$q=$pdo->prepare($sql);$q->execute($params);$items=$q->fetchAll();
require __DIR__.'/../../includes/header.php';
?>
<style>.ver-hero{background:linear-gradient(120deg,#172d53,#245caa);color:white;border-radius:15px;padding:22px;margin-bottom:18px}.ver-hero h2{margin:0 0 6px;font:800 23px Manrope}.ver-hero p{margin:0;color:#d6e5ff}.ver-card{background:white;border:1px solid #e6edf5;border-radius:13px;padding:18px;margin-bottom:16px}.ver-filters{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.ver-filters a{padding:9px 12px;border-radius:8px;background:#eef2f8;color:#40516b;font-weight:700;font-size:12px}.ver-filters a.active{background:#245fda;color:white}.ver-table-wrap{overflow:auto}.ver-table{width:100%;border-collapse:collapse;font-size:12px}.ver-table th,.ver-table td{padding:12px 9px;border-bottom:1px solid #edf1f6;text-align:left;vertical-align:top}.ver-table th{background:#f5f8fc}.ver-table input{padding:8px;border:1px solid #dce4ef;border-radius:7px;width:150px}.ver-action{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.ver-action button{padding:8px 10px;border:0;border-radius:7px;font-weight:800;cursor:pointer}.ver-action .approve{background:#dcf8e8;color:#176d40}.ver-action .reject{background:#ffe6e8;color:#a1222d}.ver-alert{padding:11px;border-radius:8px;margin-bottom:12px;background:#e6f8ee;color:#176d40}.ver-error{background:#fff0f0;color:#a1222d}.ver-status{display:inline-block;border-radius:20px;padding:5px 8px;background:#fff4d7;color:#996400;font-weight:800}.ver-file{color:#245fda;font-weight:800}</style>
<section class="ver-hero"><h2>Verifikasi Surat Izin & Sakit</h2><p>Periksa pengajuan siswa dan tetapkan keputusan verifikasi.</p></section>
<?php if($notice):?><div class="ver-alert"><?=h($notice)?></div><?php endif;?><?php if($errors):?><div class="ver-alert ver-error"><?php foreach($errors as $e):?><div><?=h($e)?></div><?php endforeach;?></div><?php endif;?>
<section class="ver-card"><nav class="ver-filters"><?php foreach(['menunggu'=>'Menunggu','disetujui'=>'Disetujui','ditolak'=>'Ditolak','semua'=>'Semua'] as $v=>$label):?><a class="<?=$status===$v?'active':''?>" href="?status=<?=h($v)?>"><?=h($label)?></a><?php endforeach;?></nav><div class="ver-table-wrap"><table class="ver-table"><thead><tr><th>Siswa</th><th>Jenis / Periode</th><th>Surat</th><th>Keterangan</th><th>Status</th><th>Verifikasi</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="6">Tidak ada pengajuan pada filter ini.</td></tr><?php else:foreach($items as $it):?><tr><td><strong><?=h($it['nama'])?></strong><br><small><?=h($it['nisn']?:$it['nis'])?> · <?=h($it['rombel'])?></small></td><td><?=h(ucfirst($it['jenis']))?><br><?=h($it['tanggal_mulai'])?> – <?=h($it['tanggal_selesai'])?></td><td><span class="ver-file"><?=h($it['file_asli'])?></span><br><small>File disimpan di penyimpanan aplikasi; akses unduh privat perlu dihubungkan sebelum dipakai.</small></td><td><?=h($it['keterangan'])?></td><td><span class="ver-status"><?=h(ucfirst($it['status']))?></span></td><td><?php if($it['status']==='menunggu'):?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf_verifikasi'])?>"><input type="hidden" name="id" value="<?=(int)$it['id']?>"><input name="catatan" maxlength="500" placeholder="Catatan (opsional)"><div class="ver-action"><button class="approve" name="keputusan" value="disetujui">Setujui</button><button class="reject" name="keputusan" value="ditolak">Tolak</button></div></form><?php else:?><?=h($it['catatan_verifikasi']?:'-')?><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php require __DIR__.'/../../includes/footer.php'; ?>
